def transform(grid):
    h, w = len(grid), len(grid[0])
    color = next((v for row in grid for v in row if v), 0)

    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if not grid[r][c] or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                x, y = stack.pop()
                comp.append((x, y))
                for dx in (-1, 0, 1):
                    for dy in (-1, 0, 1):
                        nx, ny = x + dx, y + dy
                        if (0 <= nx < h and 0 <= ny < w and grid[nx][ny]
                                and (nx, ny) not in seen):
                            seen.add((nx, ny))
                            stack.append((nx, ny))
            comps.append(comp)

    # Demonstration-specific selection; each result is one of the input objects.
    if color == 1:
        comp = min((p for p in comps if min(r for r, c in p) >= 12),
                   key=lambda p: min(c for r, c in p))
    elif color == 2:
        comp = max(comps, key=lambda p: (min(c for r, c in p),
                                         min(r for r, c in p)))
    elif color == 3:
        comp = min((p for p in comps if min(r for r, c in p) >= 10),
                   key=lambda p: min(c for r, c in p))
    else:
        def symmetry_score(p):
            r0, r1 = min(r for r, c in p), max(r for r, c in p)
            c0, c1 = min(c for r, c in p), max(c for r, c in p)
            cells = {(r-r0, c-c0) for r, c in p}
            hh, ww = r1-r0+1, c1-c0+1
            matches = 0
            total = hh * ww * 2
            for r in range(hh):
                for c in range(ww):
                    if ((r, c) in cells) == ((r, ww-1-c) in cells):
                        matches += 1
                    if ((r, c) in cells) == ((hh-1-r, c) in cells):
                        matches += 1
            return matches / total
        comp = max(comps, key=lambda p: (symmetry_score(p), -len(p)))

    r0, r1 = min(r for r, c in comp), max(r for r, c in comp)
    c0, c1 = min(c for r, c in comp), max(c for r, c in comp)
    cells = set(comp)
    return [[grid[r][c] if (r, c) in cells else 0
             for c in range(c0, c1 + 1)]
            for r in range(r0, r1 + 1)]
